// EDUVERSE chunk: A — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_A = [{"bahas":"Mengajar adalah tindakan khas yang dilakukan guru dalam pekerjaannya, sama seperti mengobati adalah tindakan khas yang dilakukan dokter dalam pekerjaannya. Pasangan lain menunjukkan hubungan pekerjaan dengan tempat bekerja, dengan hasil pekerjaan, atau dengan alat yang dipakai, bukan hubungan pekerjaan dengan tindakan khasnya.","id":"APU01","kunci":2,"opsi":["Nelayan : Laut","Penjahit : Pakaian","Dokter : Mengobati","Petani : Cangkul","Pedagang : Pasar"],"soal":"Manakah pasangan kata yang hubungannya sama dengan hubungan pada pasangan Guru : Mengajar?","subtes":"Penalaran Umum"},{"bahas":"Semua siswa kelas sebelas yang mengikuti lomba sains termasuk anggota klub robotik, dan semua anggota klub robotik harus mengikuti pelatihan dasar, sehingga semua siswa kelas sebelas yang mengikuti lomba sains itu juga harus mengikuti pelatihan dasar. Pernyataan lain membalik hubungan yang dinyatakan premis atau bertentangan dengan premis.","id":"APU02","kunci":0,"opsi":["Semua siswa kelas sebelas yang mengikuti lomba sains harus mengikuti pelatihan dasar.","Semua siswa yang mengikuti pelatihan dasar adalah anggota klub robotik.","Sebagian siswa kelas sebelas yang mengikuti lomba sains tidak harus mengikuti pelatihan dasar.","Semua anggota klub robotik adalah siswa kelas sebelas yang mengikuti lomba sains.","Tidak ada siswa kelas sebelas yang mengikuti lomba sains yang harus mengikuti pelatihan dasar."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua anggota klub robotik harus mengikuti pelatihan dasar. Premis 2: Semua siswa kelas sebelas yang mengikuti lomba sains adalah anggota klub robotik. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Eko menempati kursi nomor 1, dan Fitri tepat di sebelah kanan Candra sehingga pasangan Candra-Fitri hanya dapat menempati kursi nomor 2 dan 3, nomor 3 dan 4, atau nomor 4 dan 5. Pasangan pada kursi nomor 2 dan 3 memaksa Bimo menempati kursi nomor 5, yang dilarang syarat. Pasangan pada kursi nomor 3 dan 4 tidak memungkinkan Dewi berada di antara Bimo dan Candra. Tersisa pasangan pada kursi nomor 4 dan 5, dengan susunan Eko, Bimo, Dewi, Candra, Fitri. Dalam susunan tersebut Bimo duduk tepat di sebelah kiri Dewi, sedangkan pernyataan lain tidak sesuai dengan susunan itu.","id":"APU03","kunci":4,"opsi":["Candra duduk di kursi nomor 3.","Fitri duduk di antara Candra dan Dewi.","Bimo duduk di kursi paling kanan.","Dewi duduk tepat di sebelah kanan Candra.","Bimo duduk tepat di sebelah kiri Dewi."],"soal":"Lima siswa, yaitu Bimo, Candra, Dewi, Eko, dan Fitri, duduk berjajar pada kursi nomor 1 sampai nomor 5 dari kiri ke kanan. Diketahui: Dewi duduk di antara Bimo dan Candra; Eko duduk di kursi nomor 1; Fitri duduk tepat di sebelah kanan Candra; Bimo tidak duduk di kursi nomor 5. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Setiap suku adalah pangkat tiga dari bilangan berurutan: 1 pangkat 3 sama dengan 1, 2 pangkat 3 sama dengan 8, 3 pangkat 3 sama dengan 27, 4 pangkat 3 sama dengan 64, dan 5 pangkat 3 sama dengan 125. Suku berikutnya adalah 6 pangkat 3, yaitu 216.","id":"APU04","kunci":1,"opsi":["196","216","205","225","180"],"soal":"Pola bilangan 1, 8, 27, 64, 125, ... dilanjutkan oleh bilangan ...","subtes":"Penalaran Umum"},{"bahas":"Aturan mewajibkan setiap anggota OSIS yang mengikuti rapat untuk membawa buku catatan dan tiba sebelum rapat dimulai. Rudi adalah anggota OSIS yang mengikuti rapat, sehingga kewajiban tersebut berlaku untuk Rudi. Hal lain seperti peran Rudi dalam rapat, lamanya keanggotaan, kelengkapan catatan, atau kegiatan lain Rudi tidak dinyatakan dalam informasi yang diberikan.","id":"APU05","kunci":3,"opsi":["Rudi memimpin rapat OSIS pada hari ini.","Rudi sudah menjadi anggota OSIS sejak awal tahun ajaran.","Rudi akan mencatat seluruh keputusan rapat dengan lengkap.","Rudi membawa buku catatan dan tiba sebelum rapat dimulai.","Rudi hari ini hanya mengikuti rapat OSIS dan tidak mengikuti kegiatan lain."],"soal":"Di sebuah sekolah berlaku aturan: setiap anggota OSIS yang mengikuti rapat wajib membawa buku catatan dan tiba sebelum rapat dimulai. Hari ini Rudi, anggota OSIS, mengikuti rapat OSIS. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Ungkapan 'kerja sama' ditulis sebagai dua kata yang terpisah, keduanya dengan huruf kecil di tengah kalimat. Penulisan serangkai, penulisan dengan huruf kapital pada kata kedua di tengah kalimat, dan penulisan dengan tanda hubung tidak sesuai dengan kaidah.","id":"APPU01","kunci":4,"opsi":["Kerjasama antara pemuda desa dan warga berjalan dengan baik.","Pemuda desa dan warga menjalin kerjasama yang erat.","Pemuda desa dan warga menjalin kerja Sama yang erat.","Pemuda desa dan warga menjalin kerja-sama yang erat.","Pemuda desa dan warga menjalin kerja sama yang erat."],"soal":"Kalimat manakah yang menuliskan ungkapan 'kerja sama' dengan benar sesuai EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"id":"APPU02","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Sila Pancasila yang dilambangkan oleh bintang pada lambang Garuda Pancasila berbunyi ...","opsi":["Kemanusiaan yang adil dan beradab","Ketuhanan Yang Maha Esa","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"kunci":1,"bahas":"Bintang melambangkan sila Ketuhanan Yang Maha Esa. Rantai emas melambangkan sila Kemanusiaan yang adil dan beradab, pohon beringin melambangkan sila Persatuan Indonesia, kepala banteng melambangkan sila Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, dan padi dan kapas melambangkan sila Keadilan sosial bagi seluruh rakyat Indonesia."},{"id":"APPU03","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Gunung tertinggi di Pulau Jawa adalah ...","opsi":["Gunung Merapi","Gunung Slamet","Gunung Lawu","Gunung Semeru","Gunung Bromo"],"kunci":3,"bahas":"Gunung Semeru di Jawa Timur, dengan ketinggian sekitar 3.676 meter, merupakan gunung tertinggi di Pulau Jawa. Gunung Merapi, Gunung Slamet, Gunung Lawu, dan Gunung Bromo lebih rendah daripada Gunung Semeru."},{"bahas":"Nitrogen menyusun sekitar empat perlima bagian udara, jauh lebih banyak daripada oksigen yang menyusun sekitar seperlima bagian udara. Argon dan karbon dioksida hanya menyusun sebagian kecil udara, dan hidrogen hampir tidak terdapat dalam udara bebas.","id":"APPU04","kunci":0,"opsi":["Nitrogen","Oksigen","Karbon dioksida","Argon","Hidrogen"],"soal":"Gas yang paling banyak menyusun udara yang kita hirup sehari-hari adalah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Rumah Gadang adalah rumah adat masyarakat Minangkabau di Sumatera Barat, dengan atap bergonjong yang menyerupai tanduk kerbau. Daerah lain memiliki rumah adatnya sendiri yang berbeda bentuk dan namanya.","id":"APPU05","kunci":2,"opsi":["Jawa Tengah","Sulawesi Selatan","Sumatera Barat","Kalimantan Timur","Nusa Tenggara Timur"],"soal":"Rumah Gadang, rumah adat dengan atap bergonjong yang menyerupai tanduk kerbau, berasal dari daerah ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"bahas":"Bacaan menggambarkan koperasi yang dikelola siswa, kegiatan petugas piket, barang yang dijual, dan pemakaian keuntungan, lalu ditutup dengan simpulan bahwa koperasi menjadi tempat belajar berwirausaha secara nyata. Gagasan tersebut mencakup pembelajaran berhitung dengan teliti, kejujuran, dan kerja sama dalam tim. Pembahasan tentang barang dagangan saja, pergantian petugas saja, atau pemakaian keuntungan saja hanya mencakup sebagian isi bacaan, dan bacaan tidak membandingkan kesukaan siswa berbelanja di dalam dan di luar sekolah.","id":"APBM01","kunci":1,"opsi":["Koperasi siswa hanya menjual alat tulis dan camilan sehat dengan harga terjangkau bagi siswa.","Koperasi siswa menjadi sarana belajar berwirausaha, kejujuran, dan kerja sama bagi siswa.","Petugas piket koperasi harus berganti setiap minggu agar semua siswa mendapat giliran bertugas.","Keuntungan koperasi sebaiknya dipakai untuk membeli perlengkapan kelas dan membantu kegiatan sekolah.","Siswa SMP Cendekia lebih suka berbelanja di koperasi daripada berbelanja di luar sekolah."],"soal":"Koperasi siswa di SMP Cendekia dikelola sendiri oleh siswa dengan bimbingan guru. Setiap minggu, petugas piket yang berbeda bertugas melayani pembeli, mencatat pemasukan, dan menghitung sisa barang. Barang yang dijual adalah alat tulis, buku catatan, dan camilan sehat dengan harga yang terjangkau bagi siswa. Keuntungan koperasi dipakai untuk membeli perlengkapan kelas dan membantu kegiatan sekolah. Melalui kegiatan ini, siswa belajar berhitung dengan teliti, bersikap jujur saat memegang uang, dan bekerja sama dalam tim. Koperasi pun menjadi tempat belajar berwirausaha secara nyata, bukan sekadar tempat berbelanja di lingkungan sekolah. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Bacaan menyatakan balai yang lama tidak terpakai dibersihkan dan diperbaiki bersama, lalu dipakai untuk posyandu, latihan karawitan, dan belajar kelompok, dengan warga bergiliran membersihkan dan menanggung biaya perawatan dari iuran sukarela. Rangkaian fakta tersebut menunjukkan perawatan bersama membuat balai bermanfaat bagi banyak kegiatan warga. Bacaan tidak menyatakan balai dibangun baru, tidak menyatakan semua warga mengikuti karawitan, tidak membatasi iuran untuk posyandu, dan menyatakan balai ramai hampir setiap hari.","id":"APBM02","kunci":3,"opsi":["Balai RW 08 dibangun baru oleh warga pada tahun lalu.","Semua warga RW 08 mengikuti latihan karawitan setiap minggu.","Iuran sukarela warga hanya dipakai untuk kegiatan posyandu.","Perawatan bersama membuat balai pertemuan bermanfaat bagi banyak kegiatan warga.","Balai pertemuan hanya ramai pada hari pelaksanaan posyandu."],"soal":"Balai pertemuan RW 08 sempat bertahun-tahun tidak terpakai dan dipenuhi barang-barang lama. Tahun lalu, warga bergotong royong membersihkan dan memperbaiki balai itu, lalu menyusun jadwal pemakaian bersama. Kini balai dipakai untuk posyandu setiap bulan, latihan karawitan remaja setiap minggu, dan tempat belajar kelompok bagi anak-anak pada sore hari. Warga bergiliran membersihkan ruangan setelah dipakai, dan biaya perawatan dikumpulkan dari iuran sukarela. Seorang pengurus RT mengatakan balai yang dulu sepi kini hampir setiap hari ramai oleh kegiatan. Semangat menjaga balai bersama membuat satu ruangan sederhana bermanfaat bagi banyak keperluan warga. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, Bu Tini yang sudah sepuluh tahun berjualan dengan cara biasa kemudian mencoba layanan pesan antar yang baru baginya, dan bacaan menyebut keberanian mencoba cara baru sebagai penjelasnya. Makna tersebut sesuai dengan memulai sesuatu yang belum pernah dilakukan sebelumnya. Makna memperluas usaha ke daerah lain, mengikuti cara yang sudah umum, menutup usaha lama, atau memperbaiki jalan tidak sesuai dengan isi bacaan.","id":"APBM03","kunci":0,"opsi":["memulai sesuatu yang belum pernah dilakukan sebelumnya","memperluas usaha hingga ke daerah lain yang lebih jauh","mengikuti cara berjualan yang sudah umum dilakukan banyak orang","menutup usaha lama untuk membuka usaha yang baru","memperbaiki jalan yang dilalui pengantar pesanan"],"soal":"Warung makan Bu Tini berdiri di dekat gerbang kampus dan sudah berjualan selama sepuluh tahun. Tahun ini, ia merintis layanan pesan antar dengan sepeda untuk mahasiswa yang tidak sempat datang saat jam makan siang. Pesanan ditulis pada secarik kertas di papan tulis dekat warung, lalu diantar oleh anaknya yang masih duduk di bangku sekolah menengah. Pelanggan lama menyambut baik layanan ini karena mereka tetap dapat menikmati masakan warung di sela-sela kuliah. Dalam tiga bulan, jumlah pesanan antar bertambah dan Bu Tini menambah satu sepeda lagi. Keberanian mencoba cara baru membuat warung kecil itu tetap bertahan di tengah banyaknya tempat makan baru. Kata 'merintis' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata kegiatan, menggabungkan penanda sangat dan sekali, memakai bentuk jamak ganda pada para siswa-siswa, serta mengulang gagasan yang sama pada senang dan gembira. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan yang jelas, tanpa pengulangan kata, tanpa penguat ganda, tanpa bentuk jamak ganda, dan tanpa pasangan kata yang maknanya bertumpuk. Susunan lain masih mempertahankan sekurang-kurangnya satu dari kelemahan tersebut sehingga tetap tidak efektif.","id":"APBM04","kunci":4,"opsi":["Para siswa sangat antusias sekali mengikuti kegiatan tersebut karena kegiatan tersebut sangat menarik dan membuat siswa senang.","Siswa-siswa sangat antusias mengikuti kegiatan tersebut karena kegiatan tersebut menarik dan membuat siswa senang dan gembira.","Para siswa-siswa antusias mengikuti kegiatan tersebut karena menarik dan menyenangkan.","Siswa sangat antusias sekali mengikuti kegiatan yang menarik itu dan membuat siswa senang dan gembira.","Siswa sangat antusias mengikuti kegiatan tersebut karena menarik dan menyenangkan."],"soal":"SMP Pelita Bangsa mengadakan pentas seni pada akhir semester. Setiap kelas menampilkan pertunjukan, mulai dari drama pendek, tari daerah, hingga pertunjukan musik sederhana. Panitia yang terdiri atas siswa mengatur jadwal latihan, menyiapkan panggung, dan mengurus perlengkapan pertunjukan. Guru hanya mendampingi dan memberi saran ketika panitia menemui kesulitan. Para siswa-siswa sangat antusias sekali mengikuti kegiatan tersebut karena kegiatan tersebut sangat menarik sekali dan membuat para siswa menjadi senang dan gembira. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele dan menggunakan bentuk jamak ganda. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Awalan antar ditulis serangkai dengan kata yang mengikutinya sehingga bentuk yang tepat adalah antarkelas. Nama bulan ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Januari. Awalan ke pada bilangan tingkat ditulis serangkai sehingga bentuk yang tepat adalah kedua. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan antarkelas, Januari, dan kedua, sedangkan kalimat lain masih mempertahankan sekurang-kurangnya satu bentuk yang salah.","id":"APBM05","kunci":2,"opsi":["Pertandingan antar kelas itu akan diadakan pada bulan januari dan pemenangnya akan diumumkan pada upacara bendera ke dua di bulan yang sama.","Pertandingan antar kelas itu akan diadakan pada bulan Januari dan pemenangnya akan diumumkan pada upacara bendera ke dua di bulan yang sama.","Pertandingan antarkelas itu akan diadakan pada bulan Januari dan pemenangnya akan diumumkan pada upacara bendera kedua di bulan yang sama.","Pertandingan antarkelas itu akan diadakan pada bulan Januari dan pemenangnya akan diumumkan pada upacara bendera ke dua di bulan yang sama.","Pertandingan antarkelas itu akan diadakan pada bulan januari dan pemenangnya akan diumumkan pada upacara bendera kedua di bulan yang sama."],"soal":"(1) OSIS SMP Bina Karya mengadakan pekan olahraga pada akhir semester. (2) Setiap kelas mengirimkan tim untuk cabang bola voli, bulu tangkis, dan catur. (3) Pertandingan antar kelas itu akan diadakan pada bulan januari dan pemenangnya akan diumumkan pada upacara bendera ke dua di bulan yang sama. (4) Panitia menyiapkan lapangan, mengatur jadwal pertandingan, dan mencatat perolehan poin setiap kelas. (5) Kelas dengan poin tertinggi akan menerima piala bergilir dan piagam penghargaan pada akhir pekan olahraga. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Potongan 25% dari Rp120.000 adalah Rp30.000 sehingga harga setelah potongan tersebut menjadi Rp90.000. Potongan tambahan 20% dihitung dari Rp90.000, yaitu Rp18.000, sehingga harga akhir menjadi Rp90.000 dikurangi Rp18.000, yaitu Rp72.000. Potongan tambahan tidak dihitung dari harga awal sehingga total potongan bukan 45% dari Rp120.000.","id":"APK01","kunci":3,"opsi":["Rp66.000","Rp60.000","Rp84.000","Rp72.000","Rp90.000"],"soal":"Harga sebuah tas di sebuah kios adalah Rp120.000. Kios itu memberikan potongan 25% dari harga tersebut, lalu memberikan potongan tambahan 20% dari harga setelah potongan pertama. Berapa harga tas itu setelah kedua potongan tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih perbandingan adalah 5 dikurangi 3, yaitu 2 bagian, dan selisih tersebut setara dengan 16 buku sehingga satu bagian setara dengan 8 buku. Jumlah perbandingan adalah 5 ditambah 3, yaitu 8 bagian, sehingga jumlah seluruh buku adalah 8 dikali 8 buku, yaitu 64 buku. Sebagai pemeriksaan, banyak buku cerita adalah 40 buku dan banyak buku pelajaran adalah 24 buku, dengan selisih 16 buku.","id":"APK02","kunci":0,"opsi":["64 buku","48 buku","56 buku","72 buku","80 buku"],"soal":"Perbandingan banyak buku cerita dan buku pelajaran di sebuah rak adalah 5:3. Selisih banyak kedua jenis buku tersebut adalah 16 buku. Berapa jumlah seluruh buku di rak itu?","subtes":"Pengetahuan Kuantitatif"},{"id":"APK03","subtes":"Pengetahuan Kuantitatif","soal":"Bilangan berikutnya dari barisan 2, 3, 7, 16, 32, ... adalah ...","opsi":["54","55","57","59","61"],"kunci":2,"bahas":"Selisih antarsuku yang berurutan adalah 1, 4, 9, dan 16, yaitu kuadrat bilangan 1, 2, 3, dan 4. Selisih berikutnya adalah kuadrat 5, yaitu 25, sehingga bilangan berikutnya adalah 32 ditambah 25, yaitu 57."},{"bahas":"Luas segitiga sama dengan setengah dikali alas dikali tinggi, sehingga 60 sama dengan setengah dikali 12 dikali tinggi, yaitu 6 dikali tinggi. Tinggi segitiga adalah 60 dibagi 6, yaitu 10 cm. Membagi luas dengan alas tanpa memperhatikan faktor setengah akan menghasilkan 5 cm, yang bukan tinggi segitiga tersebut.","id":"APK04","kunci":4,"opsi":["5 cm","8 cm","9 cm","12 cm","10 cm"],"soal":"Luas sebuah segitiga adalah 60 cm² dan panjang alasnya adalah 12 cm. Berapa tinggi segitiga tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Jumlah nilai kelompok pertama adalah 4 dikali 7, yaitu 28, dan jumlah nilai kelompok kedua adalah 6 dikali 8, yaitu 48. Jumlah nilai seluruh siswa adalah 28 ditambah 48, yaitu 76, untuk 10 siswa, sehingga rata-rata gabungannya adalah 76 dibagi 10, yaitu 7,6. Merata-ratakan 7 dan 8 secara langsung mengabaikan perbedaan banyak siswa pada kedua kelompok sehingga menghasilkan 7,5, yang bukan rata-rata gabungan yang tepat.","id":"APK05","kunci":1,"opsi":["7,4","7,6","7,5","8,0","7,8"],"soal":"Rata-rata nilai kuis 4 siswa kelompok pertama adalah 7, sedangkan rata-rata nilai kuis 6 siswa kelompok kedua adalah 8. Berapa rata-rata nilai kuis seluruh siswa kedua kelompok tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Teks menggambarkan rangkaian festival literasi, sudut baca kelas, peningkatan kunjungan perpustakaan, dan terbentuknya kelompok baca kecil, lalu ditutup dengan simpulan bahwa kegiatan yang menyenangkan dapat menumbuhkan kebiasaan membaca. Gagasan utama mencakup seluruh isi tersebut. Pembahasan tentang bazar buku, hiasan sudut baca, atau kunjungan perpustakaan hanya mencakup sebagian isi teks, dan teks tidak menyatakan kelompok baca kecil sebagai kegiatan yang paling bermanfaat.","id":"ALBI01","kunci":0,"opsi":["Festival literasi yang menyenangkan dapat menumbuhkan kebiasaan membaca siswa.","Bazar buku murah membuat siswa membeli lebih banyak buku daripada sebelumnya.","Sudut baca kelas harus dihias dengan karya tulis dan gambar siswa.","Kunjungan ke perpustakaan sekolah meningkat setelah festival berakhir.","Kelompok baca kecil adalah kegiatan yang paling bermanfaat bagi siswa."],"soal":"Festival literasi di SMA Tunas Harapan berlangsung selama tiga hari dan diikuti seluruh siswa. Acara diawali dengan bazar buku murah, dilanjutkan dengan lomba bercerita, pembacaan puisi, dan diskusi bersama penulis buku anak. Setiap kelas juga menampilkan sudut baca hasil kreasi siswa yang dihias dengan karya tulis dan gambar. Guru bahasa Indonesia mencatat kunjungan ke perpustakaan sekolah meningkat setelah festival berakhir. Beberapa siswa bahkan membentuk kelompok baca kecil yang bertemu setiap minggu. Festival ini menunjukkan bahwa kegiatan yang menyenangkan dapat menumbuhkan kebiasaan membaca jauh lebih kuat daripada sekadar imbauan untuk membaca. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pengurus kelompok berharap kegiatan bertahan lama karena bahan bakunya mudah didapat dan tidak membutuhkan modal besar. Teks menyatakan kain perca berasal dari penjahit sekitar, pelatihan singkat diadakan pada awal tahun, anggota bekerja dua kali seminggu, dan keuntungan dibagi rata di antara anggota, sehingga pernyataan lain tidak sesuai dengan isi teks.","id":"ALBI02","kunci":4,"opsi":["Kain perca yang dipakai berasal dari pabrik tekstil besar di luar desa.","Pelatihan kerajinan diadakan setiap bulan oleh pengurus RW.","Anggota kelompok bekerja bersama setiap hari.","Keuntungan penjualan dipakai seluruhnya untuk biaya pelatihan berikutnya.","Bahan baku kerajinan mudah didapat dan kegiatan ini tidak membutuhkan modal besar."],"soal":"Di Kampung Melati, sekelompok ibu rumah tangga mengolah kain perca dari penjahit sekitar menjadi tas, dompet, dan tempat tisu. Kegiatan ini berawal dari pelatihan singkat yang diadakan pengurus RW pada awal tahun. Setiap anggota membawa peralatan jahit sendiri dari rumah dan bekerja bersama dua kali seminggu. Hasil kerajinan dijual pada bazar bulanan desa, dan keuntungannya dibagi rata di antara anggota. Sebagian anggota mengaku penghasilannya membantu biaya sekolah anak-anak mereka. Pengurus kelompok berharap kegiatan ini dapat bertahan lama karena bahan bakunya mudah didapat dan tidak membutuhkan modal besar. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan perubahan Dani dari hanya berani berbicara satu menit menjadi pembicara dalam debat antarkelas setelah berlatih minggu demi minggu, lalu menarik simpulan bahwa keberanian berbicara tumbuh melalui latihan yang bertahap. Cerita tersebut berfungsi sebagai contoh yang mendukung simpulan tersebut. Teks tidak mengklaim semua siswa pemalu pasti berhasil, tidak bertujuan menjelaskan jadwal latihan, tidak mengajak semua guru, dan tidak membandingkan Dani dengan siswa lain.","id":"ALBI03","kunci":2,"opsi":["Membuktikan bahwa semua siswa yang pemalu pasti berhasil jika bergabung dengan klub debat.","Menjelaskan jadwal latihan klub debat di sekolah Dani.","Menunjukkan bahwa keberanian berbicara tumbuh melalui latihan yang bertahap.","Mengajak semua guru menyarankan siswa pemalu untuk bergabung dengan klub debat.","Membandingkan kemampuan berbicara Dani dengan siswa lain di kelasnya."],"soal":"Ketika pertama kali diminta presentasi di depan kelas, suara Dani bergetar dan ia hanya membaca catatan tanpa menatap teman-temannya. Guru menyarankan Dani bergabung dengan klub debat yang berlatih setiap Jumat sore. Pada latihan pertama, Dani hanya berani berbicara selama satu menit. Minggu demi minggu, ia belajar menyusun argumen, mengatur napas, dan menanggapi pertanyaan lawan bicara. Setelah satu semester, Dani memberanikan diri menjadi pembicara pertama dalam debat antarkelas. Ia masih merasa gugup, tetapi gugup itu tidak lagi membuatnya diam. Pengalaman Dani menunjukkan bahwa keberanian berbicara tumbuh melalui latihan yang bertahap, bukan muncul begitu saja dalam semalam. Apa tujuan penulis menyajikan pengalaman Dani dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Ibu Wati menimbang dengan hati-hati, memberi tambahan, menanyakan kabar, dan memberi kelonggaran membayar keesokan hari, lalu lapaknya selalu ramai meskipun ia tidak memasang spanduk atau menurunkan harga. Rangkaian peristiwa tersebut menyiratkan kebaikan dan kepercayaan membuat pelanggan tetap setia tanpa promosi. Teks tidak mewajibkan pedagang memberi tambahan, tidak menyatakan harga murah sebagai satu-satunya alasan, tidak membebaskan pembeli dari membayar, dan tidak menyatakan jam buka sebagai syarat keramaian.","id":"ALBI04","kunci":1,"opsi":["Pedagang harus selalu memberi tambahan barang agar dagangannya laku.","Kebaikan dan kepercayaan dapat membuat pelanggan tetap setia tanpa promosi.","Harga sayur yang murah adalah satu-satunya alasan pembeli datang ke lapak Ibu Wati.","Pembeli yang kekurangan uang tidak perlu membayar belanjaannya.","Lapak sayur hanya ramai jika dibuka sebelum matahari terbit."],"soal":"Setiap pagi, Ibu Wati membuka lapak sayurnya di ujung gang sebelum matahari terbit. Ia selalu menimbang sayur dengan hati-hati, menambahkan segenggam cabai untuk pembeli yang berbelanja sedikit, dan menanyakan kabar anak-anak mereka. Ketika seorang pembeli kekurangan uang, Ibu Wati membiarkannya membayar keesokan hari tanpa mencatatnya sebagai utang. Lama-kelamaan, lapaknya tidak pernah sepi. Pembeli yang pindah ke kampung lain pun masih menyempatkan diri mampir. Anak-anak yang diantar orang tuanya sering menerima sepotong mentimun untuk dimakan di perjalanan pulang. Ibu Wati tidak pernah memasang spanduk atau menurunkan harga di bawah pedagang lain, tetapi lapaknya selalu ramai. Apa makna tersirat dari cerita tentang Ibu Wati dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat penolak menilai kegiatan dari jam yang dihabiskan tetapi mengabaikan keterampilan yang diperoleh siswa, lalu menjelaskan keterampilan mengatur waktu, bekerja dalam tim, dan memimpin yang terlatih melalui ekstrakurikuler. Kelemahannya terletak pada cara menilai yang hanya menghitung jam kegiatan tanpa mempertimbangkan keterampilan tersebut. Pernyataan lain tidak sesuai dengan isi teks atau bukan kelemahan yang dikemukakan teks.","id":"ALBI05","kunci":3,"opsi":["Anggapan bahwa semua siswa yang mengikuti ekstrakurikuler pasti menjadi pemimpin.","Keyakinan bahwa keterampilan memimpin hanya dapat dipelajari di dalam kelas.","Gagasan bahwa siswa yang mengikuti ekstrakurikuler tidak pernah belajar dengan disiplin.","Penilaian yang hanya menghitung jam kegiatan tanpa mempertimbangkan keterampilan yang diperoleh.","Dugaan bahwa kegiatan pramuka, olahraga, dan seni tidak membutuhkan jadwal yang teratur."],"soal":"Sebagian orang berpendapat bahwa kegiatan ekstrakurikuler hanya membuang waktu yang seharusnya dipakai untuk belajar. Pendapat ini menilai kegiatan dari jam yang dihabiskan, tetapi mengabaikan keterampilan yang diperoleh siswa di luar pelajaran. Dalam kegiatan pramuka, olahraga, dan seni, siswa belajar mengatur waktu, bekerja dalam tim, dan memimpin kelompok kecil. Keterampilan tersebut tidak selalu terlatih di dalam kelas. Banyak siswa yang mengikuti ekstrakurikuler justru lebih disiplin mengatur jadwal belajarnya karena mereka terbiasa membagi waktu. Karena itu, menilai ekstrakurikuler hanya dari banyaknya jam latihan adalah penilaian yang sempit. Menurut teks, kelemahan pendapat yang menolak kegiatan ekstrakurikuler terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan klub pekerjaan rumah yang dijalankan siswa senior, bantuan yang diberikan kepada siswa junior, dan manfaat yang diperoleh kedua pihak: siswa junior merasa lebih percaya diri, sedangkan siswa senior belajar menjelaskan gagasan dan bersabar. Gagasan utama mencakup manfaat bagi kedua pihak tersebut, bukan hanya satu rincian. Teks tidak menyatakan guru harus selalu memimpin, tidak menyatakan matematika dan sains sebagai mata pelajaran tersulit, tidak menyatakan siswa senior membutuhkan latihan tambahan, dan tidak menganjurkan pertemuan setiap hari.","id":"ALBE01","kunci":4,"opsi":["Teachers should always lead study groups because students cannot explain lessons clearly.","Mathematics and science are the most difficult subjects for junior students.","Senior students need more practice before they can help younger students.","Homework clubs should meet every day to improve students' grades.","A student-run homework club helps both younger learners and senior tutors."],"soal":"At Harapan High School, senior students run a homework club for younger students every Tuesday and Thursday afternoon. The club meets in a quiet classroom, where seniors help juniors understand difficult lessons, prepare for quizzes, and organize their study notes. Teachers only step in when a question is too hard for the tutors. After one semester, many juniors said they felt more confident in mathematics and science. The seniors also gained something valuable: they learned to explain ideas clearly and to be patient with different learners. The homework club shows that students can teach one another and that learning grows stronger when it is shared. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Para siswa menganggap membawa kertas bekas ke sekolah membosankan dan tidak perlu, sehingga mereka enggan bergabung sebelum dewan siswa menjelaskan manfaat kegiatan tersebut. Gambaran tersebut menunjukkan keengganan, yaitu ketidakinginan untuk bergabung, bukan ketidakmampuan, kegembiraan, kebanggaan, atau kesiapan.","id":"ALBE02","kunci":2,"opsi":["excited","unable","unwilling","proud","ready"],"soal":"When the student council announced a used-paper collection drive, many students were reluctant to join. They thought carrying old newspapers and notebooks to school was boring and unnecessary. The council then explained that the collected paper would be exchanged for new books for the school library. Class representatives also promised a small celebration for the class that collected the most paper. Slowly, students began bringing bundles of old paper from home, and some even asked their neighbors for more. Within a month, the school had collected enough paper to exchange for forty new books. The drive taught students that a small habit can bring a real benefit to the whole school. The word 'reluctant' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan keluarga baru ragu bergabung, tetangga mengundang anak-anak mereka bermain dan menawarkan tempat duduk serta teh, dan pada minggu ketiga keluarga itu sudah membawa raket sendiri. Rangkaian fakta tersebut menunjukkan permainan jalanan membantu warga baru merasa diterima di lingkungan itu. Teks tidak menyatakan jalan ditutup karena berbahaya, tidak menyatakan semua keluarga bermain, tidak menyatakan alasan keluarga baru pindah, dan tidak menyatakan anak-anak diwajibkan bermain berpasangan.","id":"ALBE03","kunci":0,"opsi":["The street games help new residents feel welcome in the neighborhood.","The residents close the street because the road is dangerous for cars.","All families on Melati Street play badminton every Friday evening.","The new family moved to Melati Street because of the badminton games.","Children on Melati Street are required to play badminton in pairs."],"soal":"Every Friday evening, residents of Melati Street close a short section of their quiet road for badminton games. Children play in pairs while older residents watch from folding chairs and keep score. One family always brings fried snacks, and another brings drinking water for everyone. Last month, a new family moved into the street and hesitated to join the games. Their neighbors invited the children to play and offered the parents a chair and a cup of tea. By the third Friday, the new family had started bringing their own rackets. The street games have become more than an evening activity for the people who live there. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan banyak orang tua mengatakan memperbaiki seragam jauh lebih murah daripada membeli seragam baru, terutama ketika seragam masih dalam kondisi baik. Itulah alasan yang dinyatakan teks untuk memilih perbaikan daripada pembelian baru. Teks tidak menyatakan toko memberi seragam gratis, tidak menyatakan larangan membeli seragam baru, dan catatan ukuran anak menjelaskan kemudahan layanan, bukan alasan memilih perbaikan daripada pembelian baru. Bantuan anak Pak Hasan pada tahun ajaran baru juga hanya rincian kesibukan toko.","id":"ALBE04","kunci":3,"opsi":["Because the shop gives a new uniform free with every repair.","Because Mr. Hasan's son sews buttons during the new school year.","Because parents are not allowed to buy new uniforms near the market.","Because repairing costs much less than buying a new uniform, especially when the old uniform is still in good condition.","Because Mr. Hasan keeps a notebook with each child's measurements."],"soal":"Mr. Hasan runs a small tailor shop near the market. Most of his customers are parents who bring school uniforms with torn pockets, loose buttons, or trousers that have become too short. Mr. Hasan can fix a torn pocket in one day and adjust trouser length in two days. He keeps a notebook with each child's measurements so that parents do not need to bring the child every time. Many parents say that repairing a uniform costs much less than buying a new one, especially when the uniform is still in good condition. During the new school year, the shop is so busy that Mr. Hasan asks his son to help with simple tasks such as sewing buttons. According to the passage, why do many parents choose to repair school uniforms instead of buying new ones?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Tono yang belajar memperbaiki rantai sepedanya sendiri, gagal pada percobaan awal, berhasil pada percobaan berikutnya, lalu membantu teman sekelas dan tidak lagi merasa tidak berdaya ketika menghadapi kerusakan kecil. Cerita tersebut menggambarkan nilai keterampilan perbaikan sederhana dalam membangun kemandirian dan rasa percaya diri. Teks tidak menganjurkan semua siswa bersepeda, tidak membandingkan video dengan bantuan ahli, tidak menjelaskan langkah perbaikan, dan tidak mengusulkan sekolah meminjamkan alat kepada semua siswa.","id":"ALBE05","kunci":1,"opsi":["To argue that all students should ride bicycles to school every day.","To show that learning simple repair skills builds independence and confidence.","To prove that watching repair videos is better than asking an expert for help.","To explain the steps for fixing a broken bicycle chain correctly.","To suggest that schools should lend tools to every student."],"soal":"When Tono's bicycle chain broke on his way to school, he had to walk the rest of the way and arrived late. Instead of waiting for someone to fix it, he watched a short repair video at the school library and borrowed basic tools from the security guard. His first attempt failed, and his hands were covered in oil. On his second attempt, the chain stayed in place, and Tono rode home proudly. Since then, he has fixed flat tires for classmates and taught two friends how to oil a chain. Tono still asks for help with difficult repairs, but he no longer feels helpless when something small goes wrong. What is the author's purpose in telling Tono's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 6 jam, 3 mesin menghasilkan 180 potong pakaian, sehingga satu mesin menghasilkan 60 potong pakaian dalam 6 jam atau 10 potong pakaian dalam 1 jam. Untuk 5 mesin selama 4 jam: 5 dikali 4 dikali 10 sama dengan 200 potong pakaian.","id":"APM01","kunci":1,"opsi":["180","200","220","240","150"],"soal":"Di sebuah konveksi kecil, 3 mesin jahit yang lajunya sama dapat menyelesaikan 180 potong pakaian dalam waktu 6 jam. Berapa potong pakaian yang dapat diselesaikan jika mesin yang bekerja ditambah menjadi 5 mesin dan waktu kerjanya 4 jam, dengan laju yang sama?","subtes":"Penalaran Matematika"},{"bahas":"Setiap suku adalah kuadrat dari bilangan prima yang berurutan: 2 kuadrat sama dengan 4, 3 kuadrat sama dengan 9, 5 kuadrat sama dengan 25, 7 kuadrat sama dengan 49, dan 11 kuadrat sama dengan 121. Bilangan prima berikutnya adalah 13, sehingga suku berikutnya adalah 13 kuadrat, yaitu 169.","id":"APM02","kunci":3,"opsi":["144","155","161","169","181"],"soal":"Suku berikutnya dari barisan 4, 9, 25, 49, 121, ... adalah ...","subtes":"Penalaran Matematika"},{"bahas":"Jumlah seluruh data adalah 4 + 5 + 6 + 6 + 7 + 8 + 9 + 11 = 56, sehingga rata-ratanya 56 : 8 = 7. Data sudah terurut dan dua nilai di tengah adalah 6 dan 7, sehingga mediannya (6 + 7) : 2 = 6,5. Selisih rata-rata dan median adalah 7 - 6,5 = 0,5.","id":"APM03","kunci":4,"opsi":["0","0,25","1","1,5","0,5"],"soal":"Dalam sebulan, banyak buku yang dibaca oleh 8 siswa tercatat sebagai berikut: 4, 5, 6, 6, 7, 8, 9, 11. Berapa selisih antara nilai rata-rata dan nilai tengah dari data tersebut?","subtes":"Penalaran Matematika"},{"bahas":"Peluang mendapat kelereng hijau pada pengambilan awal adalah 5 dari 8. Setelah satu kelereng hijau terambil tanpa pengembalian, tersisa 4 kelereng hijau dari 7 kelereng. Mengalikan peluang tersebut: 5/8 x 4/7 = 20/56 = 5/14.","id":"APM04","kunci":0,"opsi":["5/14","25/64","5/16","1/4","10/21"],"soal":"Di dalam sebuah kantong terdapat 5 kelereng hijau dan 3 kelereng kuning yang bentuk dan ukurannya sama. Seseorang mengambil dua kelereng dari kantong itu satu demi satu secara acak tanpa mengembalikan kelereng yang sudah terambil. Berapa peluang kedua kelereng yang terambil berwarna hijau?","subtes":"Penalaran Matematika"},{"bahas":"Setelah bertambah 10%, jumlah siswa menjadi 200 + 10/100 x 200 = 200 + 20 = 220 orang. Setelah berkurang 10% dari 220 orang, jumlah siswa menjadi 220 - 10/100 x 220 = 220 - 22 = 198 orang. Kenaikan dan penurunan dengan persen yang sama tidak saling meniadakan karena penurunan dihitung dari jumlah yang lebih besar.","id":"APM05","kunci":2,"opsi":["200","220","198","202","180"],"soal":"Jumlah siswa sebuah sekolah mula-mula 200 orang. Pada tahun berikutnya jumlah siswa bertambah 10% dari jumlah sebelumnya, lalu pada tahun setelahnya jumlah siswa berkurang 10% dari jumlah tahun sebelumnya. Berapa jumlah siswa pada akhir periode tersebut?","subtes":"Penalaran Matematika"}];
